from taf.sw.reporting_portal.cmd.cmd import CommandLine
from taf.sw.reporting_portal.utils.logger import logger


def main():
    logger.define_handler()
    command_line = CommandLine()
    command_line.read_parameters_and_report_results()


if __name__ == "__main__":
    main()
